# These are the fields that are touched by a training sample.  Keeping the
# cache at the frame level (rather than caching a particular train/val list)
# makes it reusable for arbitrary center windows, dates and future split
# choices while preserving the raw T4 values byte-for-byte after decoding.
_FRAME_CACHE_FIXED_FIELDS = _MAP_FIELDS
_FRAME_CACHE_VARIABLE_FIELDS = ("gt_boxes", "gt_labels")

# These are the validated stationary-track dropout rules. The
# evaluator only scores the first 40 frames for its 4 s trajectory,
# but the bridge must be built over the complete 80-frame T4 GT window: a
# stationary vehicle may be observed again after frame 40 and that later
# sighting is needed to fill an interior gap in the first four seconds.
_BRIDGE_STATIC_SPEED_MS = 0.15
_BRIDGE_MATCH_RADIUS_M = 0.75

# T4 keyframes are 10 Hz, so this is the spacing of a history window read from
# the recorded trajectory.  The closed loop advances its own history at
# ``T4ClosedLoopConfig.dt_s`` and passes that instead.
T4_FRAME_DT_S = 0.1


def _bridge_stationary_boxes(
    fboxes: List[np.ndarray], flabels: List[np.ndarray]
) -> Tuple[List[np.ndarray], List[np.ndarray]]:
    """Bridge stationary GT dropouts in the source annotation stream.

    T4 tracker annotations occasionally omit a parked object for interior
    frames. Static sightings are clustered in the full future window
    and inserts a median representative only into interior gaps.  This is
    label preprocessing, not a traffic simulator or a prediction heuristic.
    """

    clusters: List[Dict[str, Any]] = []
    for frame_index, boxes in enumerate(fboxes):
        if boxes.shape[0] == 0:
            continue
        static = np.hypot(boxes[:, 7], boxes[:, 8]) <= _BRIDGE_STATIC_SPEED_MS
        for row, label in zip(boxes[static], flabels[frame_index][static]):
            best = None
            best_distance = _BRIDGE_MATCH_RADIUS_M
            for cluster in clusters:
                distance = float(
                    np.hypot(row[0] - cluster["cx"], row[1] - cluster["cy"])
                )
                if distance <= best_distance:
                    best_distance = distance
                    best = cluster
            if best is None:
                clusters.append(
                    {
                        "cx": float(row[0]),
                        "cy": float(row[1]),
                        "rows": [row],
                        "labels": [int(label)],
                        "frames": {frame_index},
                    }
                )
            else:
                best["rows"].append(row)
                best["labels"].append(int(label))
                best["frames"].add(frame_index)
                best["cx"] = float(np.mean([value[0] for value in best["rows"]]))
                best["cy"] = float(np.mean([value[1] for value in best["rows"]]))

    if not clusters:
        return fboxes, flabels

    output_boxes = list(fboxes)
    output_labels = list(flabels)
    for cluster in clusters:
        first = min(cluster["frames"])
        last = max(cluster["frames"])
        if last - first + 1 <= len(cluster["frames"]):
            continue  # no interior dropout (or only one sighting)

        rows = np.stack(cluster["rows"]).astype(np.float64)
        representative = np.median(rows, axis=0)
        # Circular median avoids a bogus heading near
        # zero when observations straddle the +/-pi boundary.
        representative[6] = float(
            np.arctan2(
                np.median(np.sin(rows[:, 6])), np.median(np.cos(rows[:, 6]))
            )
        )
        representative[7:9] = 0.0
        representative = representative.astype(np.float32)
        labels, counts = np.unique(
            np.asarray(cluster["labels"], dtype=np.int64), return_counts=True
        )
        representative_label = np.array([labels[np.argmax(counts)]], dtype=np.int64)

        for frame_index in range(first + 1, last):
            if frame_index in cluster["frames"]:
                continue
            existing = output_boxes[frame_index]
            if existing.shape[0]:
                distance = np.hypot(
                    existing[:, 0] - representative[0],
                    existing[:, 1] - representative[1],
                )
                if bool((distance <= _BRIDGE_MATCH_RADIUS_M).any()):
                    continue
            output_boxes[frame_index] = np.concatenate(
                (existing, representative[None]), axis=0
            )
            output_labels[frame_index] = np.concatenate(
                (output_labels[frame_index], representative_label)
            )
    return output_boxes, output_labels


def _cfg_get(config: Any, key: str, default: Any = None) -> Any:
    """Read a key from a dict, OmegaConf object, or simple namespace."""

    if config is None:
        return default
    if hasattr(config, "get"):
        try:
            value = config.get(key, default)
            return default if value is None and default is not None else value
        except TypeError:
            pass
    try:
        value = config[key]
        return default if value is None and default is not None else value
    except (KeyError, TypeError, AttributeError):
        return getattr(config, key, default)


def _as_list(value: Any) -> List[Any]:
    if value is None:
        return []
    if isinstance(value, (str, bytes)):
        return [value]
    return list(value)


def _as_bool(value: Any) -> bool:
    if isinstance(value, str):
        return value.lower() in {"1", "true", "yes", "on"}
    return bool(value)


def _wrap_angle(angle: np.ndarray) -> np.ndarray:
    return (angle + np.pi) % (2.0 * np.pi) - np.pi


def global_to_ego(poses: np.ndarray, center_pose: np.ndarray) -> np.ndarray:
    """Convert global T4 poses ``[x, y, cos, sin]`` to local ``[x, y, yaw]``.

    ``center_pose`` is the current ego pose.  The calculation is float64 until
    the caller casts to float32, matching the source sample construction and
    avoiding precision loss from large global coordinates.
    """

    poses = np.asarray(poses, dtype=np.float64)
    center_pose = np.asarray(center_pose, dtype=np.float64)
    heading = float(np.arctan2(center_pose[3], center_pose[2]))
    c, s = np.cos(-heading), np.sin(-heading)
    dx = poses[..., 0] - center_pose[0]
    dy = poses[..., 1] - center_pose[1]
    return np.stack(
        (
            dx * c - dy * s,
            dx * s + dy * c,
            _wrap_angle(np.arctan2(poses[..., 3], poses[..., 2]) - heading),
        ),
        axis=-1,
    )


def build_ego_status(
    global_poses: np.ndarray, center_pose: np.ndarray, dt: float
) -> np.ndarray:
    """Build the ``[N, 7]`` ego-status history from a pose history alone.

    ``global_poses`` is ``[N, 4]`` global ``[x, y, cos, sin]`` ordered oldest to
    newest and ``center_pose`` is the frame everything is expressed in.  The
    columns are local ``[x, y, yaw]`` followed by velocity ``[vx, vy]`` and
    acceleration ``[ax, ay]``, all in the centre frame and all differenced from
    those same poses.

    ``scalars["velocity"]`` and ``scalars["acceleration"]`` are deliberately not
    read here.  They come from ``/localization/kinematic_state`` and
    ``/localization/acceleration``, which carry three properties that make them
    unusable as a per-frame history feature: ``ekf_localizer``'s stop filter
    rewrites any speed below 0.1 m/s to exactly zero (33.6% of ``prd_jt``
    frames), the lateral components are never populated (``vy`` and ``ay`` are
    identically zero across the dataset), and the twist rides the CAN/IMU chain,
    which trails the NDT-driven pose by roughly 130 ms -- so a row would pair a
    pose with a velocity describing the state 1.3 frames earlier.  Those signals
    are also per-frame body-frame while the pose columns are centre-frame, so
    the two halves of a row disagreed about their axes during a turn.
    Differencing the poses puts every column in one frame, on one clock, and
    gives the lateral channels real values.

    The oldest rows have no predecessor to difference against.  They repeat the
    nearest well-defined row rather than reading zero, which would claim the ego
    was stationary at the start of the history window.
    """

    local = global_to_ego(global_poses, center_pose)
    n = local.shape[0]
    velocity = np.zeros((n, 2), dtype=np.float64)
    acceleration = np.zeros((n, 2), dtype=np.float64)
    if n > 1:
        velocity[1:] = np.diff(local[:, :2], axis=0) / dt
        velocity[0] = velocity[1]
    if n > 2:
        # Differencing velocity[1:] keeps the fabricated velocity[0] out of it.
        acceleration[2:] = np.diff(velocity[1:], axis=0) / dt
        acceleration[:2] = acceleration[2]
    return np.concatenate((local, velocity, acceleration), axis=-1).astype(np.float32)


def _transform_agent_boxes_to_center(
    boxes: np.ndarray,
    frame_pose: np.ndarray,
    center_pose: np.ndarray,
) -> np.ndarray:
    """Transform T4 ``[x,y,z,w,l,h,yaw,vx,vy]`` boxes into center-ego.

    T4 stores each frame's agent annotations in that frame's ego
    coordinate system.  The oracle compares all 40 future frames against one
    center-frame prediction, so both the box pose and its velocity must be
    rotated through ``heading(frame)-heading(center)``.  The box dimensions and
    height are unchanged.
    """

    values = np.asarray(boxes, dtype=np.float64).reshape(-1, 9)
    if values.shape[0] == 0:
        return np.zeros((0, 9), dtype=np.float32)
    frame_pose = np.asarray(frame_pose, dtype=np.float64)
    center_pose = np.asarray(center_pose, dtype=np.float64)
    frame_heading = float(np.arctan2(frame_pose[3], frame_pose[2]))
    center_heading = float(np.arctan2(center_pose[3], center_pose[2]))
    relative_heading = frame_heading - center_heading
    c_rel, s_rel = np.cos(relative_heading), np.sin(relative_heading)
    origin = global_to_ego(frame_pose[None], center_pose)[0, :2]

    out = values.copy()
    x_local, y_local = values[:, 0].copy(), values[:, 1].copy()
    out[:, 0] = origin[0] + x_local * c_rel - y_local * s_rel
    out[:, 1] = origin[1] + x_local * s_rel + y_local * c_rel
    # Match the source window extraction contract: it adds the
    # relative heading without wrapping.  The downstream box geometry consumes
    # sin/cos-equivalent angles, but preserving the raw representation matters
    # for byte-level oracle-label parity and avoids making this adapter's GT
    # contract subtly different from the reference loader.
    out[:, 6] = values[:, 6] + relative_heading
    vx_local, vy_local = values[:, 7].copy(), values[:, 8].copy()
    out[:, 7] = vx_local * c_rel - vy_local * s_rel
    out[:, 8] = vx_local * s_rel + vy_local * c_rel
    return out.astype(np.float32)


class T4BundleReader:
    """Random-access reader for ``derived/frames.pack``."""

    MAGIC = b"T4BUND\x00\x02"

    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._fd = os.open(self.path, os.O_RDONLY)
        self._dctx = self._make_dctx()
        size = os.path.getsize(self.path)
        tail = len(self.MAGIC) + 16
        trailer = os.pread(self._fd, tail, size - tail)
        if len(trailer) != tail or trailer[16:] != self.MAGIC:
            self.close()
            raise ValueError(f"{self.path}: not a T4 bundle")
        idx_off, idx_size = struct.unpack("<QQ", trailer[:16])
        if os.pread(self._fd, len(self.MAGIC), 0) != self.MAGIC:
            self.close()
            raise ValueError(f"{self.path}: invalid T4 bundle magic")
        raw = os.pread(self._fd, idx_size, idx_off)
        if len(raw) != idx_size:
            self.close()
            raise ValueError(f"{self.path}: truncated bundle index")
        (header_size,) = struct.unpack("<I", raw[:4])
        header = json.loads(raw[4 : 4 + header_size])
        if header.get("format") != "t4bundle" or header.get("version") != 2:
            self.close()
            raise ValueError(
                f"{self.path}: unsupported bundle "
                f"{header.get('format')}/{header.get('version')}"
            )
        self.n_frames = int(header["n_frames"])
        pos = 4 + header_size
        self._offsets = np.frombuffer(raw, np.uint64, self.n_frames, pos)
        pos += 8 * self.n_frames
        self._sizes = np.frombuffer(raw, np.uint64, self.n_frames, pos)
        pos += 8 * self.n_frames
        self._spec = header["fields"]
        self._counts: Dict[str, np.ndarray] = {}
        for field in self._spec:
            if field.get("variable", False):
                self._counts[field["name"]] = np.frombuffer(
                    raw, np.uint32, self.n_frames, pos
                )
                pos += 4 * self.n_frames
        self.field_spec = {
            field["name"]: {
                "shape": field["shape"][1:]
                if field.get("variable", False)
                else field["shape"],
                "dtype": field["dtype"],
                "variable": field.get("variable", False),
            }
            for field in self._spec
        }
        self._cached_index = -1
        self._cached_frame: Optional[Dict[str, np.ndarray]] = None

    @staticmethod
    def _make_dctx():
        try:
            import zstandard as zstd
        except ImportError as exc:  # pragma: no cover - environment dependent
            raise ImportError(
                "T4 derived/frames.pack requires zstandard; install the "
                "repository requirements"
            ) from exc
        return zstd.ZstdDecompressor()

    def frame(self, index: int) -> Dict[str, np.ndarray]:
        if not 0 <= int(index) < self.n_frames:
            raise IndexError(f"{self.path}: frame {index} outside [0, {self.n_frames})")
        index = int(index)
        if index == self._cached_index:
            assert self._cached_frame is not None
            return self._cached_frame
        compressed = os.pread(
            self._fd, int(self._sizes[index]), int(self._offsets[index])
        )
        # bytearray keeps returned arrays writable when callers convert them to
        # tensors or apply augmentation in-place.
        raw = bytearray(self._dctx.decompress(compressed))
        out: Dict[str, np.ndarray] = {}
        pos = 0
        for field in self._spec:
            name = field["name"]
            dtype = np.dtype(field["dtype"])
            shape = list(field["shape"])
            if field.get("variable", False):
                shape[0] = int(self._counts[name][index])
            count = int(np.prod(shape)) if shape else 1
            out[name] = np.frombuffer(raw, dtype, count, pos).reshape(shape)
            pos += count * dtype.itemsize
        if pos != len(raw):
            raise ValueError(
                f"{self.path}: frame {index} has {len(raw) - pos} trailing bytes"
            )
        self._cached_index, self._cached_frame = index, out
        return out

    def close(self) -> None:
        if getattr(self, "_fd", None) is not None:
            os.close(self._fd)
            self._fd = None

    def __del__(self):  # pragma: no cover - best-effort cleanup
        try:
            self.close()
        except Exception:
            pass


class T4FrameCache:
    """Validated, frame-level memmap cache for the direct T4 layout.

    ``frames.pack`` is an excellent archival format, but it is intentionally
    a frame-compressed container.  The old training reader therefore decoded
    every frame in a scene once *per DataLoader worker* to assemble the GT
    cache.  With eight DDP ranks and two workers per rank, the same scene was
    decompressed up to sixteen times before the first epoch could settle.

    This cache stores only the fields consumed by the training contract. Fixed map
    tensors are stored as one ``.npy`` memmap per field; variable GT boxes and
    labels are padded to the maximum number of agents in that scene and are
    accompanied by per-frame counts.  The source ``frames.pack`` size and
    mtime are recorded in ``meta.json`` so stale labels cannot be silently
    used.  Cache construction is explicit (``scripts/build_t4_frame_cache.py``)
    and never happens inside a DataLoader worker.
    """

    def __init__(self, cache_dir: Path, metadata: Mapping[str, Any]):
        self.cache_dir = Path(cache_dir)
        self.metadata = dict(metadata)
        self.n_frames = int(self.metadata["n_frames"])
        self.max_agents = int(self.metadata["max_agents"])
        self._arrays: Dict[str, np.ndarray] = {}
        for field in (*_FRAME_CACHE_FIXED_FIELDS, "gt_boxes", "gt_labels", "gt_counts"):
            path = self.cache_dir / f"{field}.npy"
            if not path.is_file():
                raise FileNotFoundError(f"T4 frame cache is incomplete: missing {path}")
            # r+ avoids the read-only numpy warning in torch.from_numpy while
            # the reader itself never writes to the mapped arrays.  A cache is
            # a derived artifact owned by the training user, not source data.
            self._arrays[field] = np.load(path, mmap_mode="r+")

        expected = {
            "lanes": (self.n_frames, 140, 20, 33),
            "lanes_speed": (self.n_frames, 140, 1),
            "lanes_has_speed": (self.n_frames, 140, 1),
            "route": (self.n_frames, 25, 20, 33),
            "route_speed": (self.n_frames, 25, 1),
            "route_has_speed": (self.n_frames, 25, 1),
            "polygons": (self.n_frames, 10, 40, 3),
            "lines": (self.n_frames, 60, 20, 4),
            "gt_boxes": (self.n_frames, self.max_agents, 9),
            "gt_labels": (self.n_frames, self.max_agents),
            "gt_counts": (self.n_frames,),
        }
        for field, shape in expected.items():
            actual = tuple(self._arrays[field].shape)
            if actual != shape:
                self.close()
                raise ValueError(
                    f"T4 frame cache {self.cache_dir}: {field} has shape "
                    f"{actual}, expected {shape}"
                )

    @staticmethod
    def cache_dir_for(scene_dir: Path, root: Path, cache_root: Path) -> Path:
        # ``Path.resolve()`` performs filesystem metadata lookups.  The
        # source scene is on NFS, so derive the relative cache path using
        # lexical absolute paths; cache validation below is the only place
        # that needs to touch the source filesystem.
        scene_dir = Path(os.path.abspath(scene_dir))
        root = Path(os.path.abspath(root))
        cache_root = Path(os.path.abspath(cache_root))
        try:
            relative = scene_dir.relative_to(root)
        except ValueError as exc:
            raise ValueError(
                f"T4 scene {scene_dir} is outside dataset root {root}; "
                "cannot derive a safe frame-cache path"
            ) from exc
        return cache_root / relative

    @staticmethod
    def _source_signature(scene_dir: Path) -> Dict[str, Any]:
        source = Path(scene_dir) / "derived" / "frames.pack"
        stat = source.stat()
        return {
            "source_size": int(stat.st_size),
            "source_mtime_ns": int(stat.st_mtime_ns),
        }

    @classmethod
    def open(
        cls,
        scene_dir: Path,
        root: Path,
        cache_root: Path,
        *,
        require: bool = False,
        verify_source: bool = True,
    ) -> Optional["T4FrameCache"]:
        cache_dir = cls.cache_dir_for(scene_dir, root, cache_root)
        meta_path = cache_dir / "meta.json"
        if not meta_path.is_file():
            if require:
                raise FileNotFoundError(
                    f"required T4 frame cache is missing: {cache_dir}; "
                    "run scripts/build_t4_frame_cache.py first"
                )
            return None
        try:
            metadata = json.loads(meta_path.read_text())
            if int(metadata.get("version", -1)) != T4_FRAME_CACHE_VERSION:
                raise ValueError(
                    f"unsupported cache version {metadata.get('version')}; "
                    f"expected {T4_FRAME_CACHE_VERSION}"
                )
            if verify_source:
                signature = cls._source_signature(scene_dir)
                for key, value in signature.items():
                    if int(metadata.get(key, -1)) != int(value):
                        raise ValueError(
                            f"source signature mismatch for {key}: "
                            f"cache={metadata.get(key)!r}, source={value!r}"
                        )
            return cls(cache_dir, metadata)
        except Exception:
            if require:
                raise
            return None

    def frame(self, index: int) -> Dict[str, np.ndarray]:
        index = int(index)
        if not 0 <= index < self.n_frames:
            raise IndexError(f"T4 frame cache index {index} outside [0, {self.n_frames})")
        count = int(self._arrays["gt_counts"][index])
        return {
            **{
                field: self._arrays[field][index]
                for field in _FRAME_CACHE_FIXED_FIELDS
            },
            "gt_boxes": self._arrays["gt_boxes"][index, :count],
            "gt_labels": self._arrays["gt_labels"][index, :count],
        }

    def close(self) -> None:
        # Releasing the memmap objects closes their descriptors once no view is
        # retained by the caller.  Samples copy/stack the GT rows before a
        # scene is evicted, while map tensors are consumed immediately.
        self._arrays.clear()


def build_t4_frame_cache(
    scene_dir: str | Path,
    root: str | Path,
    cache_root: str | Path,
    *,
    overwrite: bool = False,
) -> Dict[str, Any]:
    """Build one validated frame cache by scanning ``frames.pack`` once.

    The function is intentionally single-scene and process-safe.  The command
    line wrapper can parallelize independent scenes, but a partially written
    cache is never visible: all arrays and metadata are written in a temporary
    directory and atomically renamed only after the complete scan succeeds.
    """

    scene_dir = Path(scene_dir).resolve()
    root = Path(root).resolve()
    cache_root = Path(cache_root).resolve()
    cache_root.mkdir(parents=True, exist_ok=True)
    cache_dir = T4FrameCache.cache_dir_for(scene_dir, root, cache_root)

    if not overwrite:
        existing = T4FrameCache.open(scene_dir, root, cache_root, require=False)
        if existing is not None:
            result = {
                "scene": str(scene_dir.relative_to(root)),
                "cache_dir": str(cache_dir),
                "n_frames": existing.n_frames,
                "max_agents": existing.max_agents,
                "built": False,
            }
            existing.close()
            return result

    bundle = T4BundleReader(scene_dir / "derived" / "frames.pack")
    required = set(_FRAME_CACHE_FIXED_FIELDS) | set(_FRAME_CACHE_VARIABLE_FIELDS)
    missing = sorted(required.difference(bundle.field_spec))
    if missing:
        bundle.close()
        raise KeyError(f"{scene_dir}: frames.pack is missing cache fields {missing}")
    counts = bundle._counts.get("gt_boxes")
    label_counts = bundle._counts.get("gt_labels")
    if counts is None or label_counts is None or not np.array_equal(counts, label_counts):
        bundle.close()
        raise ValueError(f"{scene_dir}: gt_boxes/gt_labels variable counts disagree")
    n_frames = int(bundle.n_frames)
    max_agents = int(np.max(counts)) if n_frames else 0

    temp_dir = Path(
        tempfile.mkdtemp(prefix=f".{cache_dir.name}.tmp-", dir=str(cache_root))
    )
    arrays: Dict[str, np.memmap] = {}
    try:
        shapes: Dict[str, Tuple[int, ...]] = {}
        for field in _FRAME_CACHE_FIXED_FIELDS:
            spec = bundle.field_spec[field]
            shapes[field] = (n_frames, *tuple(int(v) for v in spec["shape"]))
            arrays[field] = np.lib.format.open_memmap(
                temp_dir / f"{field}.npy",
                mode="w+",
                dtype=np.dtype(spec["dtype"]),
                shape=shapes[field],
            )
        arrays["gt_boxes"] = np.lib.format.open_memmap(
            temp_dir / "gt_boxes.npy",
            mode="w+",
            dtype=np.dtype(bundle.field_spec["gt_boxes"]["dtype"]),
            shape=(n_frames, max_agents, 9),
        )
        arrays["gt_labels"] = np.lib.format.open_memmap(
            temp_dir / "gt_labels.npy",
            mode="w+",
            dtype=np.dtype(bundle.field_spec["gt_labels"]["dtype"]),
            shape=(n_frames, max_agents),
        )
        arrays["gt_counts"] = np.lib.format.open_memmap(
            temp_dir / "gt_counts.npy",
            mode="w+",
            dtype=np.int32,
            shape=(n_frames,),
        )

        for frame_index in range(n_frames):
            frame = bundle.frame(frame_index)
            for field in _FRAME_CACHE_FIXED_FIELDS:
                arrays[field][frame_index] = frame[field]
            frame_boxes = np.asarray(frame["gt_boxes"]).reshape(-1, 9)
            frame_labels = np.asarray(frame["gt_labels"]).reshape(-1)
            count = int(frame_boxes.shape[0])
            if count != int(counts[frame_index]) or count != int(frame_labels.shape[0]):
                raise ValueError(
                    f"{scene_dir}: inconsistent GT count at frame {frame_index}"
                )
            arrays["gt_counts"][frame_index] = count
            if count:
                arrays["gt_boxes"][frame_index, :count] = frame_boxes
                arrays["gt_labels"][frame_index, :count] = frame_labels

        for array in arrays.values():
            array.flush()
        bundle.close()
        arrays.clear()

        metadata = {
            "version": T4_FRAME_CACHE_VERSION,
            "scene": str(scene_dir.relative_to(root)),
            "n_frames": n_frames,
            "max_agents": max_agents,
            "fields": [*_FRAME_CACHE_FIXED_FIELDS, *_FRAME_CACHE_VARIABLE_FIELDS, "gt_counts"],
            **T4FrameCache._source_signature(scene_dir),
        }
        (temp_dir / "meta.json").write_text(json.dumps(metadata, indent=2) + "\n")
        if cache_dir.exists():
            if not overwrite:
                raise FileExistsError(f"cache appeared while building: {cache_dir}")
            shutil.rmtree(cache_dir)
        cache_dir.parent.mkdir(parents=True, exist_ok=True)
        os.replace(temp_dir, cache_dir)
        return {
            "scene": str(scene_dir.relative_to(root)),
            "cache_dir": str(cache_dir),
            "n_frames": n_frames,
            "max_agents": max_agents,
            "built": True,
        }
    except Exception:
        try:
            bundle.close()
        except Exception:
            pass
        arrays.clear()
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise


class T4LidarPackReader:
    """Random-access reader for T4 ``LIDAR_CONCAT.pack`` files."""

    MAGIC = b"T4PACK\x00\x01"

    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._fd = os.open(self.path, os.O_RDONLY)
        self._dctx = self._make_dctx()
        size = os.path.getsize(self.path)
        trailer = os.pread(self._fd, 24, size - 24)
        if len(trailer) != 24 or trailer[16:] != self.MAGIC:
            self.close()
            raise ValueError(f"{self.path}: not a T4 LiDAR pack")
        index_offset, index_size = struct.unpack("<QQ", trailer[:16])
        if os.pread(self._fd, len(self.MAGIC), 0) != self.MAGIC:
            self.close()
            raise ValueError(f"{self.path}: invalid T4 LiDAR pack magic")
        index = json.loads(
            self._dctx.decompress(os.pread(self._fd, index_size, index_offset))
        )
        if index.get("format") != "t4pack" or index.get("version") != 1:
            self.close()
            raise ValueError(
                f"{self.path}: unsupported LiDAR pack "
                f"{index.get('format')}/{index.get('version')}"
            )
        self.n_frames = int(index["n_frames"])
        self.frames = index["frames"]

    @staticmethod
    def _make_dctx():
        try:
            import zstandard as zstd
        except ImportError as exc:  # pragma: no cover - environment dependent
            raise ImportError(
                "T4 data/LIDAR_CONCAT.pack requires zstandard; install the "
                "repository requirements"
            ) from exc
        return zstd.ZstdDecompressor()

    @staticmethod
    def _decode_frame(compressed: bytes, dtypes: Sequence[str], n: int) -> np.ndarray:
        try:
            import zstandard as zstd
        except ImportError as exc:  # pragma: no cover - checked in __init__
            raise ImportError("zstandard is required for T4 LiDAR") from exc
        raw = zstd.ZstdDecompressor().decompress(compressed)
        out = np.empty((n, 5), dtype=np.float32)
        prefix = 0
        while prefix < len(dtypes) and dtypes[prefix] == "f4s":
            prefix += 1
        pos = 0
        if prefix and n:
            planes = np.frombuffer(
                raw, np.uint8, count=4 * n * prefix, offset=0
            ).reshape(prefix, 4, n)
            out[:, :prefix] = np.ascontiguousarray(
                planes.transpose(2, 0, 1)
            ).view(np.float32).reshape(n, prefix)
            pos = 4 * n * prefix
        for column in range(prefix, len(dtypes)):
            dtype = dtypes[column]
            if dtype == "u1":
                out[:, column] = np.frombuffer(raw, np.uint8, n, pos)
                pos += n
            elif dtype == "i1":
                out[:, column] = np.frombuffer(raw, np.int8, n, pos)
                pos += n
            elif dtype == "f4s":
                planes = np.frombuffer(raw, np.uint8, 4 * n, pos).reshape(4, n)
                out[:, column] = np.ascontiguousarray(planes.T).reshape(-1).view(
                    np.float32
                )
                pos += 4 * n
            else:
                raise ValueError(f"{column}: unknown T4 pack dtype {dtype!r}")
        if pos != len(raw):
            raise ValueError(
                f"T4 LiDAR frame has {len(raw) - pos} trailing bytes"
            )
        return out

    def read_frame(self, index: int) -> np.ndarray:
        index = int(index)
        if not 0 <= index < self.n_frames:
            raise IndexError(f"{self.path}: frame {index} outside pack")
        frame = self.frames[index]
        compressed = os.pread(self._fd, int(frame["size"]), int(frame["offset"]))
        return self._decode_frame(compressed, frame["dtypes"], int(frame["n_points"]))

    def close(self) -> None:
        if getattr(self, "_fd", None) is not None:
            os.close(self._fd)
            self._fd = None

    def __del__(self):  # pragma: no cover - best-effort cleanup
        try:
            self.close()
        except Exception:
            pass


def _relative_scene_path(scene_dir: Path, root: Path) -> str:
    try:
        return str(scene_dir.relative_to(root))
    except ValueError:
        return str(scene_dir)


class T4SceneReader:
    """Lazily opened scene reader used by :class:`T4Dataset`."""

    def __init__(self, scene_dir: str | Path, root: str | Path, config: Any):
        self.scene_dir = Path(scene_dir)
        self.root = Path(root)
        # Resolve the configured camera slots before touching the raw scene.
        self.camera_names = self._resolve_camera_names(config)
        derived = self.scene_dir / "derived"
        if not derived.is_dir():
            raise FileNotFoundError(f"T4 scene has no derived directory: {self.scene_dir}")
        self.meta = json.loads((derived / "meta.json").read_text())
        with np.load(derived / "scalars.npz", allow_pickle=False) as values:
            self.scalars = {name: values[name] for name in values.files}
        self.n_frames = int(self.meta.get("n_frames", self.scalars["trajectory"].shape[0]))
        if self.scalars["trajectory"].shape[0] != self.n_frames:
            raise ValueError(f"{self.scene_dir}: trajectory/meta frame count mismatch")

        names_path = derived / "cam_names.json"
        if not names_path.is_file():
            raise FileNotFoundError(f"{self.scene_dir}: missing derived/cam_names.json")
        self.scene_camera_names = [str(name) for name in json.loads(names_path.read_text())]
        lookup = {name.upper(): i for i, name in enumerate(self.scene_camera_names)}
        missing = [name for name in self.camera_names if name.upper() not in lookup]
        if missing:
            raise ValueError(
                f"{self.scene_dir}: configured T4 cameras are absent: {missing}; "
                f"available cameras: {self.scene_camera_names}"
            )
        self.camera_indices = [lookup[name.upper()] for name in self.camera_names]
        intrinsics = np.asarray(self.scalars["cam_intrinsics"], dtype=np.float64)
        extrinsics = np.asarray(self.scalars["cam_extrinsics"], dtype=np.float64)
        if intrinsics.shape[0] != len(self.scene_camera_names):
            raise ValueError(f"{self.scene_dir}: camera intrinsics/name count mismatch")
        if extrinsics.shape != (len(self.scene_camera_names), 4, 4):
            raise ValueError(f"{self.scene_dir}: camera extrinsics have wrong shape")

        # These values are invariant for every frame in a scene.  Keeping
        # them here avoids five matrix inversions and repeated indexing into
        # the full 11-camera calibration arrays for every training window.
        self._selected_intrinsics = np.ascontiguousarray(
            intrinsics[self.camera_indices], dtype=np.float32
        )
        self._selected_extrinsics = np.ascontiguousarray(
            extrinsics[self.camera_indices], dtype=np.float32
        )
        self._selected_world_to_cam = np.ascontiguousarray(
            np.linalg.inv(extrinsics[self.camera_indices]), dtype=np.float32
        )

        # Camera filenames are invariant inside a scene.  Resolve the export
        # convention once instead of probing both 5-digit and 4-digit paths
        # for every sample (five cameras times every training window).  The
        # fallback scan keeps support for sparse/mixed exports where frame 0
        # is absent.
        image_data_root = self.scene_dir / "data"
        self._camera_dirs = [image_data_root / name for name in self.camera_names]
        self._camera_digits = [
            self._find_camera_digits(directory) for directory in self._camera_dirs
        ]

        self._bundle: Optional[T4BundleReader] = None
        self._lidar: Optional[T4LidarPackReader] = None
        self._pdm_reference_cache = None
        self._oracle_device = str(
            _cfg_get(
                config,
                "t4_oracle_device",
                _cfg_get(config, "t4_pdm_reference_device", "gpu"),
            )
            or "gpu"
        ).lower()
        if _as_bool(_cfg_get(config, "t4_load_oracle_targets", False)):
            # GPU oracle scoring is intentionally cache-free: the evaluator
            # generates the PDM-Closed denominator online from the loader's
            # scene arrays.  A cache is only opened for the explicit CPU
            # reference path, where it is the sole permitted denominator
            # source.
            pdm_cache_root = _cfg_get(config, "t4_pdm_reference_cache_dir", None)
            allow_progress_fallback = _as_bool(
                _cfg_get(config, "t4_allow_pdm_progress_fallback", False)
            )
            if self._oracle_device == "cpu":
                cache_required = _as_bool(
                    _cfg_get(
                        config,
                        "t4_pdm_reference_cache_required",
                        not allow_progress_fallback,
                    )
                )
                if pdm_cache_root in (None, "", "null", "None"):
                    if cache_required:
                        raise FileNotFoundError(
                            "CPU T4 oracle training requires "
                            "config.t4_pdm_reference_cache_dir; build the PDM-Closed "
                            "reference cache first"
                        )
                else:
                    from t4_e2e_devkit.evaluation.reference.pdm_closed import (
                        T4PDMReferenceCache,
                        T4PDMReferenceConfig,
                    )

                    self._pdm_reference_cache = T4PDMReferenceCache.open(
                        self.scene_dir,
                        self.root,
                        Path(str(pdm_cache_root)),
                        config=T4PDMReferenceConfig.from_config(config),
                        require=cache_required,
                        verify_source=_as_bool(
                            _cfg_get(config, "t4_pdm_reference_verify_source", True)
                        ),
                    )
        # Future agent GT is read from the same compressed bundle as the map,
        # but it is independent of the training center.  A scene-level cache
        # changes the access pattern from 80 decompressions per sample to one
        # sequential scene scan per worker/scene.  The cached arrays are small
        # (ragged boxes and labels only); map tensors are still decoded only for
        # the requested center frame.
        self._gt_boxes_cache: Optional[List[np.ndarray]] = None
        self._gt_labels_cache: Optional[List[np.ndarray]] = None
        self._gt_frames: Optional[Dict[int, tuple]] = None
        self._gt_fields_ok = False
        self._frame_cache: Optional[T4FrameCache] = None
        cache_root = _cfg_get(config, "t4_frame_cache_dir", None)
        if cache_root not in (None, "", "null", "None"):
            self._frame_cache = T4FrameCache.open(
                self.scene_dir,
                self.root,
                Path(str(cache_root)),
                require=_as_bool(_cfg_get(config, "t4_frame_cache_required", False)),
                verify_source=_as_bool(
                    _cfg_get(config, "t4_frame_cache_verify_source", True)
                ),
            )

    @staticmethod
    def _find_camera_digits(directory: Path) -> int:
        for digits in (5, 4):
            if (directory / f"{0:0{digits}d}.jpg").is_file():
                return digits
        try:
            with os.scandir(directory) as entries:
                for entry in entries:
                    if not entry.is_file() or not entry.name.lower().endswith(".jpg"):
                        continue
                    stem = entry.name[:-4]
                    if stem.isdigit():
                        return len(stem)
        except FileNotFoundError:
            pass
        # The missing-camera policy determines whether this becomes a hard
        # error or an explicit zero slot.  Keep the canonical export width so
        # the diagnostic can report the expected path.
        return 5

    @staticmethod
    def _resolve_camera_names(config: Any) -> List[str]:
        configured = _as_list(_cfg_get(config, "camera_names", None))
        if not configured:
            # The direct T4 adapter is intentionally explicit.  A dynamic
            # number of cameras would not match the fixed camera-aware
            # register tensor, so callers must configure the camera vocabulary.
            raise ValueError(
                "T4 reader requires config.camera_names so camera order and "
                "the number of camera registers are fixed"
            )
        return normalize_t4_camera_names(configured)

    @property
    def trajectory(self) -> np.ndarray:
        return np.asarray(self.scalars["trajectory"])

    def _bundle_reader(self) -> T4BundleReader:
        if self._bundle is None:
            self._bundle = T4BundleReader(self.scene_dir / "derived" / "frames.pack")
        return self._bundle

    def _gt_frame(self, index: int) -> Dict[str, np.ndarray]:
        """Read one GT frame from the raw Tier4 frame bundle.

        Frames decode lazily and memoize per index: a sample touches 81 of a
        scene's ~600 frames, and under a shuffled loader most scene visits are
        one-window, so the old whole-scene eager decode (~135 ms) paid for
        frames nobody read.  ``frames.pack`` is frame-compressed, so random
        access decodes exactly one record.  Repeat windows in the same scene
        still amortize through the memo.
        """

        if self._frame_cache is not None:
            cached = self._frame_cache.frame(index)
            return {
                "gt_boxes": cached["gt_boxes"],
                "gt_labels": cached["gt_labels"],
            }

        entry = self._gt_frames.get(int(index)) if self._gt_frames is not None else None
        if entry is None:
            self._check_gt_fields()
            frame = self._bundle_reader().frame(int(index))
            entry = (
                np.ascontiguousarray(
                    np.asarray(frame["gt_boxes"], dtype=np.float32).reshape(-1, 9)
                ).copy(),
                np.ascontiguousarray(
                    np.asarray(frame["gt_labels"], dtype=np.int64).reshape(-1)
                ).copy(),
            )
            if self._gt_frames is None:
                self._gt_frames = {}
            self._gt_frames[int(index)] = entry
        return {"gt_boxes": entry[0], "gt_labels": entry[1]}

    def _check_gt_fields(self) -> None:
        """Validate GT field availability once (the old eager loader's checks)."""

        if self._gt_fields_ok:
            return
        bundle = self._bundle_reader()
        direct_fields = set(bundle.field_spec)
        if {"gt_boxes", "gt_labels"}.issubset(direct_fields):
            self._gt_fields_ok = True
            return
        partial_direct = direct_fields.intersection({"gt_boxes", "gt_labels"})
        if partial_direct:
            raise KeyError(
                f"{self.scene_dir}: derived/frames.pack has only {sorted(partial_direct)}; "
                "both gt_boxes and gt_labels are required"
            )
        raise KeyError(
            f"{self.scene_dir}: raw Tier4 derived/frames.pack has no complete "
            "gt_boxes/gt_labels fields; scene tar/gt sidecar inputs are not "
            "supported by the T4 reader"
        )

    def _ensure_gt_cache(self) -> None:
        """Load the ragged agent fields once for this scene reader.

        ``frames.pack`` is frame-compressed, so asking for only two fields
        still requires decompression of the record.  Loading the records in
        order once is substantially cheaper than repeatedly decoding the same
        80-frame windows after the DataLoader shuffles centers.  Copies are
        intentional: :class:`T4BundleReader` replaces its one-frame byte
        buffer on the next call.
        """

        if self._frame_cache is not None or self._gt_boxes_cache is not None:
            return
        bundle = self._bundle_reader()
        direct_fields = set(bundle.field_spec)
        if {"gt_boxes", "gt_labels"}.issubset(direct_fields):
            boxes: List[np.ndarray] = []
            labels: List[np.ndarray] = []
            for frame_index in range(self.n_frames):
                frame = bundle.frame(frame_index)
                boxes.append(
                    np.ascontiguousarray(
                        np.asarray(frame["gt_boxes"], dtype=np.float32).reshape(-1, 9)
                    ).copy()
                )
                labels.append(
                    np.ascontiguousarray(
                        np.asarray(frame["gt_labels"], dtype=np.int64).reshape(-1)
                    ).copy()
                )
            self._gt_boxes_cache = boxes
            self._gt_labels_cache = labels
            return
        partial_direct = direct_fields.intersection({"gt_boxes", "gt_labels"})
        if partial_direct:
            raise KeyError(
                f"{self.scene_dir}: derived/frames.pack has only {sorted(partial_direct)}; "
                "both gt_boxes and gt_labels are required"
            )
        raise KeyError(
            f"{self.scene_dir}: raw Tier4 derived/frames.pack has no complete "
            "gt_boxes/gt_labels fields; scene tar/gt sidecar inputs are not "
            "supported by the T4 reader"
        )

    def frame(self, index: int) -> Dict[str, np.ndarray]:
        """Return one raw derived T4 frame.

        This is intentionally a small public boundary for evaluators and the
        closed-loop replay adapter.  Training samples expose future oracle
        boxes only when ``t4_load_oracle_targets`` is enabled; the ragged
        fields are kept as Python lists by :func:`t4_collate`.
        """

        if self._frame_cache is not None:
            result = dict(self._frame_cache.frame(int(index)))
        else:
            result = dict(self._bundle_reader().frame(int(index)))
        return result

    def _lidar_reader(self) -> T4LidarPackReader:
        if self._lidar is None:
            meta_path = self.meta.get("lidar_pack")
            if meta_path:
                path = Path(meta_path)
                if not path.is_absolute():
                    path = self.root / path
            else:
                path = self.scene_dir / "data" / "LIDAR_CONCAT.pack"
            self._lidar = T4LidarPackReader(path)
        return self._lidar

    def _read_lidar(self, frame: int) -> np.ndarray:
        first = int(self.meta.get("lidar_first_frame", 0))
        count = int(self.meta.get("lidar_frames", self.n_frames))
        if not first <= frame < first + count:
            raise ValueError(f"{self.scene_dir}: no LiDAR frame for scene index {frame}")
        pack_index = frame + int(self.meta.get("frame_offset", 0))
        return self._lidar_reader().read_frame(pack_index)

    def _read_camera_features(self, frame: int, config: Any) -> Dict[str, Any]:
        image_size_hw = _cfg_get(config, "t4_image_size_hw", None)
        if image_size_hw is None:
            # The historical image_size is [W, H]. The explicit T4 key
            # is [H, W] and removes ambiguity at the direct-reader boundary.
            default_image_size_wh = (
                T4_DEFAULT_IMAGE_SIZE_HW[1],
                T4_DEFAULT_IMAGE_SIZE_HW[0],
            )
            image_size = _as_list(
                _cfg_get(config, "image_size", default_image_size_wh)
            )
            if len(image_size) != 2:
                raise ValueError("config.image_size must contain [W, H]")
            width, height = int(image_size[0]), int(image_size[1])
        else:
            image_size_hw = _as_list(image_size_hw)
            if len(image_size_hw) != 2:
                raise ValueError("config.t4_image_size_hw must contain [H, W]")
            height, width = int(image_size_hw[0]), int(image_size_hw[1])
        if height <= 0 or width <= 0:
            raise ValueError(f"invalid T4 image size {(height, width)}")

        presence = self.scalars.get("cam_presence")
        if presence is not None and not bool(presence[frame].shape[0] == len(self.scene_camera_names)):
            raise ValueError(f"{self.scene_dir}: cam_presence/name count mismatch")

        policy = str(_cfg_get(config, "t4_missing_camera_policy", "error")).lower()
        if policy not in {"error", "zero"}:
            raise ValueError("t4_missing_camera_policy must be 'error' or 'zero'")
        images: List[np.ndarray] = []
        scaled_k: List[np.ndarray] = []
        ego_to_camera: List[np.ndarray] = []
        present: List[bool] = []
        decoder = str(_cfg_get(config, "t4_image_decoder", "pil")).lower()
        if decoder != "pil":
            raise ValueError(
                "T4 reader uses the PIL image path; "
                "t4_image_decoder must be 'pil'"
            )
        raw_uint8 = _as_bool(_cfg_get(config, "t4_image_uint8_transfer", False))
        raw_draft = _as_bool(_cfg_get(config, "t4_image_draft_decode", False))
        if raw_uint8 and policy != "error":
            # A missing slot is defined as "exactly the ImageNet mean", which is
            # zero only *after* normalisation.  255*0.485 = 123.675 is not an
            # integer, so the byte path cannot express that slot exactly.
            raise ValueError(
                "t4_image_uint8_transfer requires t4_missing_camera_policy='error'; "
                "the zero-filled missing-camera slot cannot be represented in uint8"
            )
        for camera_slot, (name, scene_index, camera_dir, digits) in enumerate(
            zip(
                self.camera_names,
                self.camera_indices,
                self._camera_dirs,
                self._camera_digits,
            )
        ):
            # Raw T4 exports use both historical five-digit filenames and an
            # alternate four-digit serialization.  The calibration/presence
            # arrays remain authoritative when present; filename probing only
            # resolves that raw-export naming difference.
            image_path = camera_dir / f"{frame:0{digits}d}.jpg"
            available = bool(presence[frame, scene_index]) if presence is not None else True
            if available and not image_path.is_file():
                # Sparse exports can mix conventions within one directory;
                # retain the old fallback only on the exceptional path.
                alternate_digits = 4 if digits == 5 else 5
                alternate = camera_dir / f"{frame:0{alternate_digits}d}.jpg"
                if alternate.is_file():
                    image_path = alternate
                else:
                    available = False
            if not available:
                if policy == "error":
                    raise FileNotFoundError(
                        f"{self.scene_dir}: missing camera {name} at frame {frame}"
                    )
                # Mean RGB becomes zero after ImageNet normalization.  This is
                # an explicit fixed-slot mask, not an accidental camera drop.
                images.append(np.zeros((3, height, width), dtype=np.float32))
                scaled_k.append(self._selected_intrinsics[camera_slot].copy())
                ego_to_camera.append(self._selected_world_to_cam[camera_slot])
                present.append(False)
                continue

            with Image.open(image_path) as image:
                # Intrinsics scale against the true sensor resolution, so the
                # source size must be read before a draft decode shrinks it.
                source_width, source_height = image.size
                if raw_draft:
                    # JPEG DCT-domain scaled decode: libjpeg emits the
                    # smallest power-of-two scale still >= the target, and the
                    # BICUBIC resize below covers the remainder.  2.4x faster
                    # than full decode + resize on the 2880x1860 WIDE cameras;
                    # pixel delta vs the full path is mean 0.75/255 (a
                    # different resampling chain), so this is A/B-gated.
                    image.draft("RGB", (width, height))
                image = image.convert("RGB")
                # Match the feature-builder contract: the source path calls
                # ``Image.resize(size)`` without a resampling argument, whose
                # RGB default in the shared Pillow runtime is BICUBIC.
                image = image.resize((width, height))
                if raw_uint8:
                    # Hand the resized bytes over untouched; the model forward path
                    # applies the identical /255, -mean, /std in fp32 on the
                    # device.  One sample is 46 MB as float32 and 11.6 MB as
                    # uint8, and that volume crosses a DataLoader worker
                    # boundary and the host-to-device copy on every step.
                    pixels = np.asarray(image, dtype=np.uint8)
                else:
                    pixels = np.asarray(image, dtype=np.float32) / 255.0
            if not raw_uint8:
                pixels = (
                    pixels - np.asarray([0.485, 0.456, 0.406], dtype=np.float32)
                ) / np.asarray([0.229, 0.224, 0.225], dtype=np.float32)
            images.append(np.ascontiguousarray(pixels.transpose(2, 0, 1)))
            scale_x = width / float(source_width)
            scale_y = height / float(source_height)
            camera_k = self._selected_intrinsics[camera_slot].astype(
                np.float64, copy=True
            )
            camera_k[0, 0] *= scale_x
            camera_k[0, 2] *= scale_x
            camera_k[1, 1] *= scale_y
            camera_k[1, 2] *= scale_y
            scaled_k.append(camera_k.astype(np.float32))
            # T4 stores camera -> ego/base_link. The legacy field is
            # named world_2_cam and expects the inverse transform.
            ego_to_camera.append(self._selected_world_to_cam[camera_slot])
            present.append(True)
        result: Dict[str, Any] = {
            "cam_K": torch.from_numpy(np.stack(scaled_k, axis=0)),
            "world_2_cam": torch.from_numpy(np.stack(ego_to_camera, axis=0)),
            "cam_extrinsics": torch.from_numpy(self._selected_extrinsics),
            "cam_presence": torch.tensor(present, dtype=torch.bool),
        }
        result["image"] = torch.from_numpy(np.stack(images, axis=0))
        return result  # type: ignore[return-value]

    @staticmethod
    def _lidar_histogram(points: np.ndarray, config: Any) -> torch.Tensor:
        point_range = _as_list(
            _cfg_get(config, "t4_lidar_range", [-122.4, -122.4, -3.0, 122.4, 122.4, 5.0])
        )
        if len(point_range) != 6:
            raise ValueError("t4_lidar_range must be [xmin,ymin,zmin,xmax,ymax,zmax]")
        image_size = [int(v) for v in _as_list(_cfg_get(config, "lidar_image_size", [518, 518]))]
        if len(image_size) != 2:
            raise ValueError("lidar_image_size must be [W, H]")
        xmin, ymin, zmin, xmax, ymax, zmax = [float(v) for v in point_range]
        points = np.asarray(points, dtype=np.float32)
        points = points[
            (points[:, 0] >= xmin)
            & (points[:, 0] < xmax)
            & (points[:, 1] >= ymin)
            & (points[:, 1] < ymax)
            & (points[:, 2] >= zmin)
            & (points[:, 2] < zmax)
        ]
        # T4's fifth channel is ring/time-lag. The input contract explicitly
        # zeroes it before BEV processing; the histogram path does
        # not consume it, but zero it here to keep the adapter contract clear.
        if points.size:
            points = points.copy()
            points[:, 4] = 0.0
        max_per_pixel = float(_cfg_get(config, "lidar_hist_max_per_pixel", 5))
        split_height = float(_cfg_get(config, "lidar_split_height", 0.2))
        use_ground = _as_bool(_cfg_get(config, "lidar_use_ground_plane", True))

        def splat(values: np.ndarray) -> np.ndarray:
            xbins = np.linspace(xmin, xmax, image_size[0] + 1)
            ybins = np.linspace(ymin, ymax, image_size[1] + 1)
            histogram = np.histogramdd(values[:, :2], bins=(xbins, ybins))[0]
            return np.minimum(histogram, max_per_pixel) / max_per_pixel

        below = points[points[:, 2] <= split_height]
        above = points[points[:, 2] > split_height]
        above_features = splat(above) if len(above) else np.zeros((image_size[0], image_size[1]))
        if use_ground:
            below_features = splat(below) if len(below) else np.zeros_like(above_features)
            features = np.stack((below_features, above_features), axis=0)
        else:
            features = above_features[None]
        # Histogram axis order follows the feature-builder contract.
        return torch.from_numpy(np.ascontiguousarray(features[None].astype(np.float32)))

    def sample(self, center: int, config: Any) -> Tuple[Dict[str, torch.Tensor], Dict[str, Any]]:
        center = int(center)
        history = int(_cfg_get(config, "t4_history_frames", T4_DEFAULT_HISTORY_FRAMES))
        future_stride = int(_cfg_get(config, "t4_future_stride", T4_DEFAULT_FUTURE_STRIDE))
        num_poses = int(_cfg_get(config, "num_poses", 8))
        # This option adds two 0.5 s waypoints to the long target, then
        # uses cubic-spline re-sampling to
        # obtain an accelerated [num_poses, 3] target.  Keep it as the
        # original config key so the T4 adapter follows the paper/code
        # contract instead of introducing a T4-only loss variant.
        long_additional_poses = int(
            _cfg_get(config, "long_trajectory_additional_poses", -1)
        )
        load_oracle_targets = _as_bool(
            _cfg_get(config, "t4_load_oracle_targets", False)
        )
        oracle_future_frames = int(
            _cfg_get(
                config,
                "t4_oracle_future_frames",
                T4_DEFAULT_ORACLE_FUTURE_FRAMES,
            )
        )
        gt_future_frames = int(
            _cfg_get(
                config,
                "t4_gt_future_frames",
                T4_DEFAULT_GT_FUTURE_FRAMES,
            )
        )
        pdm_observation_frames = int(
            _cfg_get(
                config,
                "t4_pdm_observation_frames",
                T4_DEFAULT_PDM_OBSERVATION_FRAMES,
            )
        )
        if history < 0 or future_stride <= 0 or num_poses <= 0:
            raise ValueError("invalid T4 history/future sampling parameters")
        if (
            load_oracle_targets
            and oracle_future_frames != T4_DEFAULT_ORACLE_FUTURE_FRAMES
        ):
            raise ValueError(
                "T4 oracle labels must preserve the original evaluator horizon "
                f"of {T4_DEFAULT_ORACLE_FUTURE_FRAMES} 10Hz frames"
            )
        if load_oracle_targets and gt_future_frames < oracle_future_frames:
            raise ValueError(
                "t4_gt_future_frames must cover the complete evaluator horizon; "
                f"got {gt_future_frames} < {oracle_future_frames}"
            )
        if load_oracle_targets and pdm_observation_frames != T4_DEFAULT_PDM_OBSERVATION_FRAMES:
            raise ValueError(
                "T4 PDM labels must preserve the original 5 s/10 Hz observation "
                f"({T4_DEFAULT_PDM_OBSERVATION_FRAMES} future frames)"
            )
        if load_oracle_targets and gt_future_frames < pdm_observation_frames:
            raise ValueError(
                "t4_gt_future_frames must cover the original PDM observation; "
                f"got {gt_future_frames} < {pdm_observation_frames}"
            )
        future_indices = center + future_stride * np.arange(1, num_poses + 1)
        long_future_indices = None
        if long_additional_poses > 0:
            long_num_poses = num_poses + long_additional_poses
            long_future_indices = center + future_stride * np.arange(
                1, long_num_poses + 1
            )
        oracle_future_indices = center + np.arange(1, oracle_future_frames + 1)
        gt_future_indices = center + np.arange(1, gt_future_frames + 1)
        history_indices = np.arange(center - history, center + 1)
        target_indices = future_indices
        if long_future_indices is not None:
            target_indices = np.concatenate((target_indices, long_future_indices))
        all_indices = np.concatenate(
            (
                history_indices,
                gt_future_indices if load_oracle_targets else target_indices,
            )
        )
        if all_indices.min() < 0 or all_indices.max() >= self.n_frames:
            raise IndexError(
                f"{self.scene_dir}: center {center} cannot form T4 window "
                f"(history={history}, poses={num_poses}, stride={future_stride})"
            )
        valid_mask = self.scalars.get("valid_mask")
        if valid_mask is not None and not bool(np.all(valid_mask[all_indices])):
            raise ValueError(f"{self.scene_dir}: center {center} touches invalid T4 frames")

        center_pose = self.trajectory[center]
        target_local = global_to_ego(self.trajectory[future_indices], center_pose).astype(np.float32)
        target_long_local = None
        if long_future_indices is not None:
            # Match the target-builder contract: x=0..N-1 is the longer
            # trajectory and the eight regular target samples are shifted
            # toward its endpoint using the paper's cubic-spline rule.
            long_global = self.trajectory[long_future_indices]
            x = np.arange(long_global.shape[0], dtype=np.float32)
            alpha = 2.0 * long_additional_poses / (
                num_poses * (num_poses + 1)
            )
            x_new = np.arange(num_poses, dtype=np.float32)
            x_new += np.cumsum((x_new + 1.0) * alpha)
            long_local = global_to_ego(long_global, center_pose)
            spline_values = []
            for dimension in range(long_local.shape[-1]):
                spline = CubicSpline(x, long_local[:, dimension])
                spline_values.append(spline(x_new))
            target_long_local = np.stack(spline_values, axis=-1).astype(np.float32)

        # Route intent is represented continuously by the complete route-lane
        # token stream and destination.  Do not quantize it into a handcrafted
        # command or leak T4's historical turn-indicator state into ego input.
        center_frame = self.frame(center)
        # The same builder the closed loop runs on its live pose history, so
        # training and rollout see one definition of the ego-status columns.
        ego_status = build_ego_status(
            self.trajectory[history_indices], center_pose, T4_FRAME_DT_S
        )

        goal_global = np.asarray(self.scalars["goal"], dtype=np.float64)
        goal_local_xyh = global_to_ego(goal_global[None], center_pose)[0]
        goal_clamp_m = _cfg_get(config, "t4_goal_clamp_m", None)
        if goal_clamp_m is not None:
            goal_clamp_m = float(goal_clamp_m)
            goal_distance = float(np.hypot(goal_local_xyh[0], goal_local_xyh[1]))
            if goal_clamp_m > 0 and goal_distance > goal_clamp_m:
                goal_local_xyh[:2] *= goal_clamp_m / goal_distance
        goal_pose = np.asarray(
            [
                goal_local_xyh[0],
                goal_local_xyh[1],
                np.cos(goal_local_xyh[2]),
                np.sin(goal_local_xyh[2]),
            ],
            dtype=np.float32,
        )

        features: Dict[str, torch.Tensor] = {
            "ego_status": torch.from_numpy(ego_status),
            "ego_shape": torch.from_numpy(np.asarray(self.scalars["shape"], dtype=np.float32)),
            "goal_pose": torch.from_numpy(goal_pose),
            # Kept separate from ``ego_status`` because this is the runtime
            # actuator state, not a learned history feature. The
            # control/deployment contract needs the current velocity,
            # acceleration, steering angle and yaw rate to turn the selected
            # trajectory into an acceleration + steering-rate command.
            "control_state": torch.from_numpy(
                np.concatenate(
                    (
                        np.asarray(self.scalars["velocity"][center], dtype=np.float32),
                        np.asarray(self.scalars["acceleration"][center], dtype=np.float32),
                        np.asarray([self.scalars["steering"][center]], dtype=np.float32),
                        np.asarray([self.scalars["yaw_rate"][center]], dtype=np.float32),
                    )
                )
            ),
        }
        features.update(self._read_camera_features(center, config))

        use_hd_map = _as_bool(_cfg_get(config, "use_hd_map", True))
        if use_hd_map:
            frame = center_frame
            missing = [name for name in _MAP_FIELDS if name not in frame]
            if missing:
                raise KeyError(
                    f"{self.scene_dir}: HD-map bundle is missing {missing}; "
                    "T4 mode refuses to train camera-only"
                )
            # Keep the canonical names in the feature dictionary so the model
            # sees lanes, route, destination, and all map context distinctly.
            lanes_array = np.asarray(frame["lanes"], dtype=np.float32)
            route_array = np.asarray(frame["route"], dtype=np.float32)
            polygon_array = np.asarray(frame["polygons"], dtype=np.float32)
            line_array = np.asarray(frame["lines"], dtype=np.float32)
            # These four counts are tiny CPU metadata, not model inputs.  The
            # compact map encoder uses them to choose the batch rectangle
            # without synchronizing a CUDA reduction back to Python.
            map_valid_counts = (
                int(np.count_nonzero(np.abs(lanes_array).reshape(lanes_array.shape[0], -1).sum(axis=1) > 0)),
                int(np.count_nonzero(np.abs(route_array).reshape(route_array.shape[0], -1).sum(axis=1) > 0)),
                int(np.count_nonzero(np.abs(polygon_array).reshape(polygon_array.shape[0], -1).sum(axis=1) > 0)),
                int(np.count_nonzero(np.abs(line_array).reshape(line_array.shape[0], -1).sum(axis=1) > 0)),
            )
            features.update(
                {
                    "lanes": torch.from_numpy(lanes_array),
                    "lanes_speed_limit": torch.from_numpy(
                        np.asarray(frame["lanes_speed"], dtype=np.float32)
                    ),
                    "lanes_has_speed_limit": torch.from_numpy(
                        np.asarray(frame["lanes_has_speed"], dtype=np.float32)
                    ),
                    "route_lanes": torch.from_numpy(route_array),
                    "route_lanes_speed_limit": torch.from_numpy(
                        np.asarray(frame["route_speed"], dtype=np.float32)
                    ),
                    "route_lanes_has_speed_limit": torch.from_numpy(
                        np.asarray(frame["route_has_speed"], dtype=np.float32)
                    ),
                    "polygons": torch.from_numpy(polygon_array),
                    "line_strings": torch.from_numpy(line_array),
                    "map_valid_counts": map_valid_counts,
                }
            )

        if _as_list(_cfg_get(config, "lidar_pc", [])):
            features["lidar_feature"] = self._lidar_histogram(self._read_lidar(center), config)

        targets: Dict[str, Any] = {
            "trajectory": torch.from_numpy(target_local),
            "token": _relative_scene_path(self.scene_dir, self.root) + f":{center}",
        }
        if target_long_local is not None:
            targets["trajectory_long"] = torch.from_numpy(target_long_local)
        if load_oracle_targets:
            bundle = None if self._frame_cache is not None else self._bundle_reader()
            direct_fields = (
                set(_FRAME_CACHE_VARIABLE_FIELDS)
                if self._frame_cache is not None
                else set(bundle.field_spec)
            )
            has_direct_gt = set(_FRAME_CACHE_VARIABLE_FIELDS).issubset(direct_fields)
            partial_direct = direct_fields.intersection(set(_FRAME_CACHE_VARIABLE_FIELDS))
            if partial_direct and not has_direct_gt:
                raise KeyError(
                    f"{self.scene_dir}: derived/frames.pack has only "
                    f"{sorted(partial_direct)}; both gt_boxes and gt_labels are required"
                )
            if not has_direct_gt:
                raise KeyError(
                    f"{self.scene_dir}: T4 oracle training requires future GT in "
                    "the raw derived/frames.pack; scene tar/gt sidecar inputs are "
                    "not accepted, and an absent source is not an empty traffic scene"
                )

            oracle_target_local = global_to_ego(
                self.trajectory[oracle_future_indices], center_pose
            ).astype(np.float32)
            # PDM's TTC implementation evaluates each 4 s proposal one second
            # ahead, so the original observation contains the current frame
            # plus 50 future 10 Hz frames.  Keep the model target separate at
            # 40 frames; the extra ten frames are oracle-only.
            current_frame = self._gt_frame(center)
            current_boxes = np.asarray(current_frame["gt_boxes"], dtype=np.float64).reshape(-1, 9)
            current_labels = np.asarray(current_frame["gt_labels"], dtype=np.int64).reshape(-1)
            if current_boxes.shape[0] != current_labels.shape[0]:
                raise ValueError(
                    f"{self.scene_dir}: current frame {center} has mismatched GT counts"
                )
            all_agent_boxes: List[np.ndarray] = [
                _transform_agent_boxes_to_center(
                    current_boxes,
                    self.trajectory[center],
                    center_pose,
                )
            ]
            all_agent_labels: List[np.ndarray] = [current_labels.copy()]
            for frame_index in gt_future_indices:
                frame = self._gt_frame(int(frame_index))
                boxes = np.asarray(frame["gt_boxes"], dtype=np.float64).reshape(-1, 9)
                labels = np.asarray(frame["gt_labels"], dtype=np.int64).reshape(-1)
                if boxes.shape[0] != labels.shape[0]:
                    raise ValueError(
                        f"{self.scene_dir}: frame {frame_index} has "
                        f"{boxes.shape[0]} gt_boxes but {labels.shape[0]} gt_labels"
                    )
                all_agent_boxes.append(
                    _transform_agent_boxes_to_center(
                        boxes,
                        self.trajectory[int(frame_index)],
                        center_pose,
                    )
                )
                all_agent_labels.append(labels.copy())

            if _as_bool(_cfg_get(config, "t4_bridge_stationary_boxes", True)):
                all_agent_boxes, all_agent_labels = _bridge_stationary_boxes(
                    all_agent_boxes, all_agent_labels
                )

            current_agent_boxes = all_agent_boxes[0]
            current_agent_labels = all_agent_labels[0]
            future_agent_boxes = all_agent_boxes[1 : pdm_observation_frames + 1]
            future_agent_labels = all_agent_labels[1 : pdm_observation_frames + 1]
            if len(future_agent_boxes) != pdm_observation_frames:
                raise ValueError(
                    f"{self.scene_dir}: PDM observation has {len(future_agent_boxes)} "
                    f"future frames, expected {pdm_observation_frames}"
                )

            # These are deliberately target-side, ragged fields.  The model
            # never receives future boxes at deployment; they are only oracle
            # labels for the oracle scorer's BCE targets.
            targets["oracle_future_trajectory"] = torch.from_numpy(oracle_target_local)
            targets["current_agent_boxes"] = current_agent_boxes
            targets["current_agent_labels"] = current_agent_labels
            targets["future_agent_boxes"] = future_agent_boxes
            targets["future_agent_labels"] = future_agent_labels
            targets["agent_gt_available"] = True

            if str(_cfg_get(config, "t4_oracle_device", "cpu") or "cpu").lower() != "cpu":
                # GPU-oracle scene prep is proposal-independent, so it runs
                # here in the loader worker, overlapped with the GPU step,
                # instead of on the training step's critical path.  Inputs are
                # the very tensors the CPU payload would carry (float32 map
                # fields, transformed fp64 boxes), so both oracle paths see
                # identical data.
                from t4_e2e_devkit.evaluation.gpu.scene import (
                    extract_window_scene_arrays,
                )
                from t4_e2e_devkit.evaluation.reference.pdm_closed import PDM_ROADBLOCK_BUFFER_M

                scene_arrays = extract_window_scene_arrays(
                    features["lanes"].numpy(),
                    features["route_lanes"].numpy(),
                    features["polygons"].numpy(),
                    [current_agent_boxes, *future_agent_boxes],
                    [current_agent_labels, *future_agent_labels],
                    roadblock_buffer_m=float(
                        _cfg_get(
                            config,
                            "t4_drivable_area_buffer_m",
                            PDM_ROADBLOCK_BUFFER_M,
                        )
                    ),
                )
                targets["oracle_scene"] = {
                    key: torch.from_numpy(np.ascontiguousarray(value))
                    for key, value in scene_arrays.items()
                }
            if self._pdm_reference_cache is not None:
                reference = self._pdm_reference_cache.frame(center)
                # Keep the cache audit values alongside the training label.
                # They are tensors so the standard T4 collate and Lightning
                # device transfer remain deterministic; the scorer consumes
                # only ``pdm_progress``.
                targets["pdm_progress"] = torch.tensor(
                    reference["pdm_progress"], dtype=torch.float32
                )
                targets["pdm_reference_selected_proposal"] = torch.tensor(
                    reference["selected_proposal"], dtype=torch.long
                )
                targets["pdm_reference_proposal_scores"] = torch.from_numpy(
                    np.asarray(reference["proposal_scores"], dtype=np.float32)
                )
                targets["pdm_reference_trajectory"] = torch.from_numpy(
                    np.asarray(reference["reference_trajectory"], dtype=np.float32)
                )
                targets["pdm_reference_nc"] = torch.tensor(
                    reference["reference_nc"], dtype=torch.float32
                )
                targets["pdm_reference_dac"] = torch.tensor(
                    reference["reference_dac"], dtype=torch.float32
                )
                targets["pdm_reference_raw_progress"] = torch.tensor(
                    reference["reference_raw_progress"], dtype=torch.float32
                )
            elif self._oracle_device == "cpu" and not _as_bool(
                _cfg_get(config, "t4_allow_pdm_progress_fallback", False)
            ):
                raise RuntimeError(
                    "CPU T4 oracle sample has no PDM-Closed reference cache; "
                    "online PDM-Closed generation is GPU-only"
                )
        return features, targets

    def close(self) -> None:
        if self._bundle is not None:
            self._bundle.close()
            self._bundle = None
        if self._lidar is not None:
            self._lidar.close()
            self._lidar = None
        if self._frame_cache is not None:
            self._frame_cache.close()
            self._frame_cache = None
        if self._pdm_reference_cache is not None:
            self._pdm_reference_cache.close()
            self._pdm_reference_cache = None

    def __del__(self):  # pragma: no cover - best-effort cleanup
        try:
            self.close()
        except Exception:
            pass


def _load_data_list(path: str | Path) -> Tuple[Path, List[Tuple[str, int]]]:
    path = Path(path)
    spec = json.loads(path.read_text())
    if not isinstance(spec, Mapping):
        raise ValueError(f"T4 data list must be a JSON object: {path}")
    root = Path(spec.get("root", "."))
    if not root.is_absolute():
        root = (path.parent / root).resolve()
    rows: List[Tuple[str, int]] = []
    for row in spec.get("rows", []):
        if isinstance(row, Mapping):
            scene = row.get("scene", row.get("scene_dir", row.get("path")))
            center = row.get("center", row.get("center_frame"))
        else:
            if len(row) != 2:
                raise ValueError(f"invalid T4 data-list row: {row!r}")
            scene, center = row
        if scene is None or center is None:
            raise ValueError(f"invalid T4 data-list row: {row!r}")
        rows.append((str(scene), int(center)))
    if not rows:
        raise ValueError(f"T4 data list has no rows: {path}")
    return root, rows


class T4Dataset(Dataset):
    """Map-style T4 window dataset for the training loop."""

    def __init__(
        self,
        data_list: str | Path,
        config: Any,
        cache_scenes: int = 4,
        append_token_to_batch: bool = False,
    ):
        super().__init__()
        self.data_list = Path(data_list)
        self.root, self.rows = _load_data_list(self.data_list)
        self.config = config
        self.append_token_to_batch = append_token_to_batch
        self._cache: "OrderedDict[str, T4SceneReader]" = OrderedDict()
        self._cache_size = max(1, int(cache_scenes))
        if not _as_list(_cfg_get(config, "camera_names", None)):
            raise ValueError("T4Dataset requires config.camera_names")
        self._validate_window_bounds()

    def __len__(self) -> int:
        return len(self.rows)

    def _validate_window_bounds(self) -> None:
        """Reject stale lists before a worker encounters an invalid row.

        T4 lists are reusable artifacts.  A list generated for the original
        4-second model target is shorter than the 8-second raw GT window
        needed when stationary-box bridging is enabled.  Without this check,
        shuffled training can run for an arbitrary number of batches and then
        fail inside ``__getitem__`` on the first incompatible center.
        """

        history = int(_cfg_get(self.config, "t4_history_frames", T4_DEFAULT_HISTORY_FRAMES))
        future_stride = int(_cfg_get(self.config, "t4_future_stride", T4_DEFAULT_FUTURE_STRIDE))
        num_poses = int(_cfg_get(self.config, "num_poses", 8))
        if _as_bool(_cfg_get(self.config, "t4_load_oracle_targets", False)):
            required_future = int(
                _cfg_get(
                    self.config,
                    "t4_gt_future_frames",
                    T4_DEFAULT_GT_FUTURE_FRAMES,
                )
            )
        else:
            required_future = future_stride * num_poses
        if history < 0 or required_future <= 0:
            raise ValueError(
                "T4 window validation requires non-negative history and positive future horizon"
            )

        scene_lengths: Dict[str, int] = {}
        invalid: List[Tuple[str, int, int]] = []
        for scene_name, center in self.rows:
            if scene_name not in scene_lengths:
                scene_path = Path(scene_name)
                if not scene_path.is_absolute():
                    scene_path = self.root / scene_path
                meta_path = scene_path / "derived" / "meta.json"
                if meta_path.is_file():
                    meta = json.loads(meta_path.read_text())
                    n_frames = int(meta.get("n_frames", 0))
                else:
                    with np.load(scene_path / "derived" / "scalars.npz", allow_pickle=False) as values:
                        n_frames = int(values["trajectory"].shape[0])
                if n_frames <= 0:
                    raise ValueError(f"T4 scene has no valid frame count: {scene_path}")
                scene_lengths[scene_name] = n_frames
            n_frames = scene_lengths[scene_name]
            if int(center) - history < 0 or int(center) + required_future >= n_frames:
                invalid.append((scene_name, int(center), n_frames))

        if invalid:
            examples = "; ".join(
                f"{scene}:{center} (n_frames={n_frames})"
                for scene, center, n_frames in invalid[:3]
            )
            raise ValueError(
                f"T4 data list contains {len(invalid)} centers incompatible with "
                f"history={history} and future={required_future}: {examples}. "
                "Rebuild the direct list with scripts/build_t4_datalist.py using "
                "the same --gt-future-frames as the training config."
            )

    def _scene(self, scene_name: str) -> T4SceneReader:
        reader = self._cache.get(scene_name)
        if reader is None:
            scene_path = Path(scene_name)
            if not scene_path.is_absolute():
                scene_path = self.root / scene_path
            reader = T4SceneReader(scene_path, self.root, self.config)
            self._cache[scene_name] = reader
            while len(self._cache) > self._cache_size:
                _, old = self._cache.popitem(last=False)
                old.close()
        else:
            self._cache.move_to_end(scene_name)
        return reader

    def __getitem__(self, index: int):
        scene_name, center = self.rows[index]
        features, targets = self._scene(scene_name).sample(center, self.config)
        if self.append_token_to_batch:
            return features, targets, targets["token"]
        return features, targets


def t4_collate(batch: Sequence[Any], pack_agent_targets: bool = False):
    """Collate fixed tensors while preserving ragged oracle GT fields.

    ``torch.utils.data.default_collate`` cannot batch a list of per-frame
    ``[N_t,9]`` agent boxes because ``N_t`` changes with traffic.  More
    importantly, padding those boxes without a mask would make "missing GT"
    indistinguishable from "zero agents".  Fixed model inputs and the 8-point
    target are stacked.  The default keeps future boxes as ragged Python lists
    for the CPU reference/debug path; the training path can request
    ``pack_agent_targets=True`` to pad within a batch and return an explicit
    ``future_agent_mask`` for an asynchronous CUDA transfer.
    """

    if not batch:
        raise ValueError("cannot collate an empty T4 batch")
    has_tokens = len(batch[0]) == 3
    if any(len(sample) != (3 if has_tokens else 2) for sample in batch):
        raise ValueError("mixed T4 batch tuple formats")

    feature_samples = [sample[0] for sample in batch]
    target_samples = [sample[1] for sample in batch]
    feature_keys = tuple(feature_samples[0].keys())
    target_keys = tuple(target_samples[0].keys())
    if any(tuple(sample.keys()) != feature_keys for sample in feature_samples):
        raise KeyError("T4 feature keys differ between samples")
    if any(tuple(sample.keys()) != target_keys for sample in target_samples):
        raise KeyError("T4 target keys differ between samples")

    def collate_mapping(samples: Sequence[Mapping[str, Any]], keys: Sequence[str]):
        output: Dict[str, Any] = {}
        ragged_keys = {
            "current_agent_boxes",
            "current_agent_labels",
            "future_agent_boxes",
            "future_agent_labels",
            "agent_gt_available",
            "token",
            # Host-side map metadata used to avoid a GPU->CPU shape sync in
            # HDMapEncoder; keep it as a small Python object.
            "map_valid_counts",
            # Loader-side GPU-oracle scene prep: per-window dict of tensors
            # with ragged shapes (track/polygon counts vary), kept as a list.
            "oracle_scene",
        }
        for key in keys:
            values = [sample[key] for sample in samples]
            if pack_agent_targets and key == "future_agent_boxes":
                frame_count = len(values[0])
                if any(len(sample) != frame_count for sample in values):
                    raise ValueError("T4 future agent box horizons differ in one batch")
                max_agents = max(
                    1,
                    max(
                        (
                            np.asarray(frame).reshape(-1, 9).shape[0]
                            for sample in values
                            for frame in sample
                        ),
                        default=0,
                    ),
                )
                packed = torch.zeros(
                    (len(values), frame_count, max_agents, 9), dtype=torch.float32
                )
                mask = torch.zeros(
                    (len(values), frame_count, max_agents), dtype=torch.bool
                )
                for batch_index, sample in enumerate(values):
                    for frame_index, frame in enumerate(sample):
                        array = np.asarray(frame, dtype=np.float32).reshape(-1, 9)
                        count = array.shape[0]
                        if count:
                            packed[batch_index, frame_index, :count] = torch.from_numpy(
                                np.ascontiguousarray(array)
                            )
                            mask[batch_index, frame_index, :count] = True
                output[key] = packed
                output["future_agent_mask"] = mask
            elif pack_agent_targets and key == "future_agent_labels":
                frame_count = len(values[0])
                max_agents = int(output["future_agent_boxes"].shape[2])
                packed = torch.zeros(
                    (len(values), frame_count, max_agents), dtype=torch.long
                )
                for batch_index, sample in enumerate(values):
                    for frame_index, frame in enumerate(sample):
                        array = np.asarray(frame, dtype=np.int64).reshape(-1)
                        count = array.shape[0]
                        if count:
                            packed[batch_index, frame_index, :count] = torch.from_numpy(
                                np.ascontiguousarray(array)
                            )
                output[key] = packed
            elif pack_agent_targets and key == "agent_gt_available":
                output[key] = torch.as_tensor(values, dtype=torch.bool)
            elif key in ragged_keys:
                output[key] = values
            elif all(torch.is_tensor(value) for value in values):
                output[key] = torch.stack(values, dim=0)
            elif all(isinstance(value, np.ndarray) for value in values):
                output[key] = torch.from_numpy(np.stack(values, axis=0))
            else:
                raise TypeError(
                    f"unsupported non-tensor T4 field {key!r}; explicitly add it "
                    "to t4_collate if it is a new ragged field"
                )
        return output

    features = collate_mapping(feature_samples, feature_keys)
    targets = collate_mapping(target_samples, target_keys)
    if has_tokens:
        return features, targets, [sample[2] for sample in batch]
    return features, targets


def t4_collate_packed(batch: Sequence[Any]):
    """Training collate with masked, batch-local oracle target padding."""

    return t4_collate(batch, pack_agent_targets=True)


def build_t4_rows(
    scene_dir: str | Path,
    root: str | Path,
    history_frames: int = T4_DEFAULT_HISTORY_FRAMES,
    num_poses: int = 8,
    future_stride: int = T4_DEFAULT_FUTURE_STRIDE,
    gt_future_frames: int = T4_DEFAULT_GT_FUTURE_FRAMES,
    center_stride: int = T4_DEFAULT_CENTER_STRIDE,
) -> List[Tuple[str, int]]:
    """Build valid centers using the complete 8 s future GT window.

    ``center_stride`` is the spacing between consecutive training windows, in
    source frames. T4 is recorded at 10 Hz, while the source sampling policy
    uses one training window every 0.5 s. Taking every T4 frame instead puts
    one window every 0.1 s, so neighboring rows share 30 of their 31 history
    frames and 79 of their 80 future frames for little additional information.
    ``center_stride=5`` keeps the source spacing explicit.
    """

    scene_dir, root = Path(scene_dir), Path(root)
    with np.load(scene_dir / "derived" / "scalars.npz", allow_pickle=False) as values:
        n_frames = int(values["trajectory"].shape[0])
        valid_mask = values["valid_mask"].astype(bool) if "valid_mask" in values.files else None
    gt_future_frames = int(gt_future_frames)
    if gt_future_frames <= 0:
        raise ValueError("gt_future_frames must be positive")
    center_stride = int(center_stride)
    if center_stride < 1:
        raise ValueError(f"center_stride must be >= 1, got {center_stride}")
    last = n_frames - 1 - gt_future_frames
    rows: List[Tuple[str, int]] = []
    rel = _relative_scene_path(scene_dir, root)
    for center in range(int(history_frames), last + 1, center_stride):
        indices = np.concatenate(
            (
                np.arange(center - int(history_frames), center + 1),
                center + np.arange(1, gt_future_frames + 1),
            )
        )
        if valid_mask is None or bool(np.all(valid_mask[indices])):
            rows.append((rel, center))
    return rows
